  ('grovbase-shot-spec:kierunki-kreatywne-z-ok-40-r:wizualizacja-dzialania', 'Przepisy stylu › Kierunki kreatywne (z ok. 40 referencji kampanii marek, 28.10.2026)', 95, date '2026-10-27', 'creative', array['plan']::text[], 'global', '{}'::text[], 'knowledge', false, 'Wizualizacja działania', 'Kierunek: Wizualizacja działania; Kiedy: każda niewidoczna funkcja; Światło i kolor: jak sceny wyżej; Kadr i znaki rozpoznawcze: subtelny efekt graficzny bez napisów: fale dźwięku, przepływ powietrza lub wody, ślad trasy, przekrój przez materiał'),
